'use strict';
// SUSSY server: authoritative game logic. One process hosts many rooms of up to ROOM_SIZE players.
const http = require('http'), fs = require('fs'), path = require('path');
const { WebSocketServer } = require('ws');
const VERSION = '2.2.0';
const { page: PAGE, card: CARD_PNG, wide: CARD_WIDE } = loadAssets(); // the page and the two preview images; see the end of this file
const PORT = +process.env.PORT || 3000;
