      if (d.k === 'lights') this.sab = { k: 'lights', t0: now };
      else if (d.k === 'reactor') { this.sab = { k: 'reactor', t0: now, until: now + REACTOR_MS, ha: 0, hb: 0, fix: 0 }; this.assignResponders(); }
