    let top = 0, tops = []; for (const t in cnt) { if (cnt[t] > top) { top = cnt[t]; tops = [t]; } else if (cnt[t] === top) tops.push(t); }
    let id = null, tie = false; if (tops.length === 1 && tops[0] !== 'skip') id = +tops[0]; else if (tops.length > 1) tie = true;
